            <style>
            .matrix-form{display:grid;grid-template-columns:minmax(0,1fr) 180px 150px auto;gap:10px;align-items:end}.matrix-form label{display:flex;flex-direction:column;gap:6px}.matrix-form input,.matrix-form select{width:100%;margin:0}.matrix-hint,.matrix-status{min-height:20px;color:#64748b;font-size:13px}.matrix-status.success{color:#047857}.matrix-status.error{color:#b91c1c}.matrix-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}.matrix-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.matrix-box{min-height:205px;padding:15px;border:1px solid #dbe3ef;border-radius:13px;background:#fff}.matrix-box h3{display:flex;align-items:center;justify-content:space-between;gap:9px;margin:0 0 5px;font-size:16px}.matrix-box h3 span{font-size:12px;font-weight:500;color:#64748b}.matrix-box p{margin:0 0 12px;color:#64748b;font-size:12px}.matrix-box.do{border-top:4px solid #ef4444}.matrix-box.schedule{border-top:4px solid #3b82f6}.matrix-box.delegate{border-top:4px solid #f59e0b}.matrix-box.reduce{border-top:4px solid #94a3b8}.matrix-list{display:grid;gap:8px}.matrix-empty{padding:16px 8px;text-align:center;color:#94a3b8;font-size:13px}.matrix-task{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:9px;align-items:center;padding:9px;border-radius:9px;background:#f8fafc}.matrix-task.done{opacity:.58}.matrix-task input{margin:0}.matrix-task strong,.matrix-task small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.matrix-task strong{color:#334155;font-size:14px}.matrix-task.done strong{text-decoration:line-through}.matrix-task small{margin-top:3px;color:#64748b;font-size:12px}.matrix-task button{min-width:34px;padding:5px 8px}html.theme-dark .matrix-box{border-color:#475569;background:#1e293b}html.theme-dark .matrix-task{background:#0f172a}html.theme-dark .matrix-task strong{color:#e2e8f0}@media(max-width:720px){.matrix-form,.matrix-grid{grid-template-columns:1fr}.matrix-form button{width:100%}}
            </style>
            <section class="tool-panel">
                <div class="matrix-form"><label>待办事项<input id="taskTitle" type="text" maxlength="160" placeholder="例如：完成客户方案" autofocus></label><label>优先级<select id="quadrant"><option value="do">重要且紧急：立即做</option><option value="schedule">重要不紧急：计划做</option><option value="delegate">紧急不重要：委派/快速处理</option><option value="reduce">不重要不紧急：减少/暂缓</option></select></label><label>截止日期（可选）<input id="dueDate" type="date"></label><button class="btn success" id="addTask" type="button">添加任务</button></div>
                <p class="matrix-hint">用四象限先判断任务，再执行：紧急且重要的先做；重要但不紧急的安排时间。</p><div class="matrix-actions"><button class="btn" id="export" type="button" disabled>下载 Markdown</button><button class="btn secondary" id="clearDone" type="button" disabled>清除已完成</button><button class="btn secondary" id="clearAll" type="button" disabled>清空全部</button></div><p class="matrix-status" id="status" role="status" aria-live="polite">任务仅保存在当前浏览器，不会上传服务器。</p>
            </section>
            <section class="matrix-grid" aria-label="任务优先级四象限"><article class="matrix-box do"><h3>立即做 <span id="count-do">0 项</span></h3><p>重要且紧急</p><div class="matrix-list" id="list-do"></div></article><article class="matrix-box schedule"><h3>计划做 <span id="count-schedule">0 项</span></h3><p>重要但不紧急</p><div class="matrix-list" id="list-schedule"></div></article><article class="matrix-box delegate"><h3>委派 / 快速处理 <span id="count-delegate">0 项</span></h3><p>紧急但不重要</p><div class="matrix-list" id="list-delegate"></div></article><article class="matrix-box reduce"><h3>减少 / 暂缓 <span id="count-reduce">0 项</span></h3><p>不重要也不紧急</p><div class="matrix-list" id="list-reduce"></div></article></section>
            <script>
            (()=>{'use strict';const STORAGE_KEY='office_priority_matrix_v1',MAX_TASKS=200,quadrants=['do','schedule','delegate','reduce'],$=id=>document.getElementById(id);let tasks=[];function status(message,type=''){const node=$('status');node.textContent=message;node.className='matrix-status '+type;}function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(tasks));}catch{status('浏览器无法保存草稿，请先导出 Markdown 备份。','error');}}function safeDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value)?value:'';}function render(){quadrants.forEach(key=>{const list=$('list-'+key),items=tasks.filter(task=>task.quadrant===key);list.replaceChildren();$('count-'+key).textContent=items.length+' 项';if(!items.length){const empty=document.createElement('div');empty.className='matrix-empty';empty.textContent='暂时没有任务';list.appendChild(empty);return;}items.forEach(task=>{const row=document.createElement('div'),check=document.createElement('input'),body=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small'),remove=document.createElement('button');row.className='matrix-task'+(task.done?' done':'');check.type='checkbox';check.checked=task.done;check.setAttribute('aria-label','标记“'+task.title+'”已完成');check.addEventListener('change',()=>{task.done=check.checked;save();render();});title.textContent=task.title;meta.textContent=task.due?'截止：'+task.due:(task.done?'已完成':'未设置截止日期');body.append(title,meta);remove.className='btn secondary small';remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','删除“'+task.title+'”');remove.addEventListener('click',()=>{tasks=tasks.filter(item=>item.id!==task.id);save();render();status('已删除任务。','success');});row.append(check,body,remove);list.appendChild(row);});});const has=tasks.length>0;$('export').disabled=!has;$('clearAll').disabled=!has;$('clearDone').disabled=!tasks.some(task=>task.done);}function add(){const title=$('taskTitle').value.trim(),quadrant=$('quadrant').value,due=safeDate($('dueDate').value);if(!title){status('请先填写待办事项。','error');$('taskTitle').focus();return;}if(tasks.length>=MAX_TASKS){status('最多保存 '+MAX_TASKS+' 项任务，请先清理已完成任务。','error');return;}tasks.unshift({id:Date.now().toString(36)+'-'+tasks.length,title:title.slice(0,160),quadrant:quadrants.includes(quadrant)?quadrant:'do',due,done:false});$('taskTitle').value='';$('dueDate').value='';save();render();status('任务已加入“'+$('quadrant').selectedOptions[0].textContent.split('：')[1]+'”。','success');$('taskTitle').focus();}function download(){const labels={do:'立即做（重要且紧急）',schedule:'计划做（重要不紧急）',delegate:'委派 / 快速处理（紧急不重要）',reduce:'减少 / 暂缓（不重要不紧急）'},lines=['# 任务优先级矩阵','','生成时间：'+new Date().toLocaleString('zh-CN'),''];quadrants.forEach(key=>{lines.push('## '+labels[key]);const items=tasks.filter(task=>task.quadrant===key);lines.push(...(items.length?items.map(task=>'- ['+(task.done?'x':' ')+'] '+task.title+(task.due?'（截止：'+task.due+'）':'')):['- 暂无任务']),'');});const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\n')],{type:'text/markdown;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='任务优先级矩阵-'+new Date().toISOString().slice(0,10)+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Markdown 已生成并开始下载。','success');}function restore(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(Array.isArray(saved))tasks=saved.slice(0,MAX_TASKS).filter(task=>task&&typeof task.title==='string'&&quadrants.includes(task.quadrant)).map(task=>({id:String(task.id||Date.now()),title:task.title.slice(0,160),quadrant:task.quadrant,due:safeDate(task.due),done:Boolean(task.done)}));}catch{}render();} $('addTask').addEventListener('click',add);$('taskTitle').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();add();}});$('export').addEventListener('click',download);$('clearDone').addEventListener('click',()=>{tasks=tasks.filter(task=>!task.done);save();render();status('已清除完成的任务。','success');});$('clearAll').addEventListener('click',()=>{tasks=[];try{localStorage.removeItem(STORAGE_KEY);}catch{}render();status('已清空全部任务。','success');});restore();})();
            </script>
